describe('ToolRegistry schema compilation', () => {
  // specs/hal-engine-tool-input-validation/spec.md#6
  it('rejects an invalid static schema at registration', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {name: 'broken', description: 'Invalid schema', inputSchema: {type: 'invalid'}},
        async () => 'unreachable'
      )
    ).toThrow(/broken/);
  });
});

// specs/hal-engine-tool-input-validation/spec.md#2
it('rejects missing required input', async () => {
  const registry = new ToolRegistry();
  let calls = 0;
  registry.register(
    {
      name: 'weather',
      description: 'Weather',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    },
    async () => {
      calls += 1;
      return 'forecast';
    }
  );
  const response = await registry.execute('weather', {});
  expect({result: response.result, calls}).toEqual({
    result: expect.stringMatching(/location.*required|required.*location/i),
    calls: 0,
  });
});

