it('validates each current dynamic schema', async () => {
  const registry = new ToolRegistry();
  let schema = {type: 'object', required: ['first']};
  registry.register(
    () => ({name: 'dynamic', description: 'Dynamic', inputSchema: schema}),
    async () => 'accepted'
  );
  const first = await registry.execute('dynamic', {});
  schema = {type: 'object', required: ['second']};
  const second = await registry.execute('dynamic', {});
  expect([first.result, second.result]).toEqual([expect.stringContaining('first'), expect.stringContaining('second')]);
});
